import java.util.Scanner;

public class CarRental {
    private String customerName;
    private String carModel;
    private int rentalDays;
    private double kmDriven;
    private double totalBill;

    public CarRental() {
        customerName = "";
        carModel = "";
        rentalDays = 0;
        kmDriven = 0.0;
        totalBill = 0.0;
    }

    public void accept() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Customer Name: ");
        customerName = in.nextLine();
        System.out.print("Enter Car Model: ");
        carModel = in.nextLine();
        System.out.print("Enter Rental Days: ");
        rentalDays = in.nextInt();
        System.out.print("Enter Total Kilometers Driven: ");
        kmDriven = in.nextDouble();
    }

    public void calculateBill() {
        double dayCharges = rentalDays * 1200.0;
        double freeKm = rentalDays * 100.0;
        double excessKm = Math.max(0.0, kmDriven - freeKm);
        double kmCharges = excessKm * 9.50;

        double subtotal = dayCharges + kmCharges;
        double gst = 0.18 * subtotal;
        totalBill = subtotal + gst;
    }

    public void printInvoice() {
        System.out.println("\n============== DRIVEEASY CAR RENTAL ==============");
        System.out.println("Customer Name     : " + customerName);
        System.out.println("Car Model         : " + carModel);
        System.out.println("Rental Duration   : " + rentalDays + " Days");
        System.out.println("Total KM Driven   : " + kmDriven + " km");
        System.out.println("Total Amount (GST): Rs. " + totalBill);
        System.out.println("===================================================");
    }

    public static void main(String[] args) {
        CarRental rental = new CarRental();
        rental.accept();
        rental.calculateBill();
        rental.printInvoice();
    }
}
```

