import java.util.Scanner;

public class GradeDistributionCounter {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 20;
        char[] grades = new char[N];

        System.out.println("Enter grades (A/B/C/D/F) for " + N + " students:");
        for (int i = 0; i < N; i++) {
            System.out.print("Student " + (i + 1) + ": ");
            grades[i] = sc.next().toUpperCase().charAt(0);
        }

        int countA = 0, countB = 0, countC = 0, countD = 0, countF = 0;

        for (char g : grades) {
            switch (g) {
                case 'A': countA++; break;
                case 'B': countB++; break;
                case 'C': countC++; break;
                case 'D': countD++; break;
                case 'F': countF++; break;
                default:
                    System.out.println("Unrecognized grade: " + g);
            }
        }

        System.out.println("\n============== GRADE STATISTICS ==============");
        System.out.println("Grade 'A' Count : " + countA);
        System.out.println("Grade 'B' Count : " + countB);
        System.out.println("Grade 'C' Count : " + countC);
        System.out.println("Grade 'D' Count : " + countD);
        System.out.println("Grade 'F' Count : " + countF);
        System.out.printf("Percentage of 'A' Grades: %.1f%%\n", (countA * 100.0) / N);
        System.out.println("==============================================");
    }
}
