import java.util.Scanner;

public class SentencePiglatinTranslator {
    public static String toPiglatin(String word) {
        String vowels = "AEIOUaeiou";
        int firstVowelIdx = -1;

        for (int i = 0; i < word.length(); i++) {
            if (vowels.indexOf(word.charAt(i)) != -1) {
                firstVowelIdx = i;
                break;
            }
        }

        if (firstVowelIdx == 0) {
            return word + "WAY";
        } else if (firstVowelIdx > 0) {
            return word.substring(firstVowelIdx) + word.substring(0, firstVowelIdx) + "AY";
        } else {
            return word + "AY"; // No vowel
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter a sentence to translate to Piglatin:");
        String sentence = in.nextLine().trim();

        String[] words = sentence.split("\\s+");
        StringBuilder piglatin = new StringBuilder();

        for (int i = 0; i < words.length; i++) {
            piglatin.append(toPiglatin(words[i]));
            if (i < words.length - 1) piglatin.append(" ");
        }

        System.out.println("\nOriginal Sentence : " + sentence);
        System.out.println("Piglatin Sentence : " + piglatin.toString());
    }
}
```

