import java.util.Scanner;

public class UniqueNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter positive integer: ");
        int n = sc.nextInt();

        if (n <= 0) {
            System.out.println("Please enter a positive integer.");
            return;
        }

        int[] digitCounts = new int[10];
        int temp = n;
        boolean isUnique = true;

        while (temp > 0) {
            int d = temp % 10;
            digitCounts[d]++;
            if (digitCounts[d] > 1) {
                isUnique = false;
                break;
            }
            temp /= 10;
        }

        System.out.println();
        if (isUnique) {
            System.out.println(n + " is a UNIQUE NUMBER (no duplicate digits).");
        } else {
            System.out.println(n + " is NOT a Unique Number (contains duplicate digits).");
        }
    }
}
```

