import java.util.Scanner;

public class MatrixMultiplication3x3 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        final int N = 3;
        int[][] A = new int[N][N];
        int[][] B = new int[N][N];
        int[][] C = new int[N][N];

        System.out.println("Enter 9 elements for Matrix A:");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) A[i][j] = in.nextInt();
        }

        System.out.println("Enter 9 elements for Matrix B:");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) B[i][j] = in.nextInt();
        }

        // Multiply A and B
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                for (int k = 0; k < N; k++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }

        System.out.println("\nMatrix A:");
        printMat(A);

        System.out.println("\nMatrix B:");
        printMat(B);

        System.out.println("\nProduct Matrix C = A x B:");
        printMat(C);
    }

    private static void printMat(int[][] mat) {
        for (int[] row : mat) {
            for (int val : row) System.out.printf("%6d", val);
            System.out.println();
        }
    }
}
```

