import java.util.Scanner;

public class MenuTwistedPrimeHollowSquare {
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("========== UTILITY MENU ==========");
        System.out.println("1. Twisted Prime Number Check");
        System.out.println("2. Hollow Square Star Pattern");
        System.out.print("Enter choice (1 or 2): ");
        int choice = sc.nextInt();

        switch (choice) {
            case 1:
                System.out.print("Enter positive number: ");
                int num = sc.nextInt();

                boolean p1 = isPrime(num);
                int temp = num, rev = 0;
                while (temp > 0) {
                    rev = rev * 10 + (temp % 10);
                    temp /= 10;
                }
                boolean p2 = isPrime(rev);

                System.out.println("Original Number : " + num + " (Prime: " + p1 + ")");
                System.out.println("Reversed Number : " + rev + " (Prime: " + p2 + ")");

                if (p1 && p2) {
                    System.out.println(num + " is a TWISTED PRIME NUMBER.");
                } else {
                    System.out.println(num + " is NOT a Twisted Prime Number.");
                }
                break;

            case 2:
                System.out.print("Enter side dimension n (3 to 10): ");
                int n = sc.nextInt();
                System.out.println("\nHollow Square Pattern:");
                for (int i = 1; i <= n; i++) {
                    for (int j = 1; j <= n; j++) {
                        if (i == 1 || i == n || j == 1 || j == n) {
                            System.out.print("* ");
                        } else {
                            System.out.print("  ");
                        }
                    }
                    System.out.println();
                }
                break;

            default:
                System.out.println("Invalid Selection.");
        }
    }
}
```

